CREATE TABLE IF NOT EXISTS dos.compliance_frameworks (
  framework_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id VARCHAR(16) NOT NULL,
  code VARCHAR(100) NOT NULL,
  name TEXT NOT NULL,
  version VARCHAR(20),
  status VARCHAR(50) NOT NULL DEFAULT 'active',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  deleted_at TIMESTAMPTZ,
  is_deleted BOOLEAN NOT NULL DEFAULT FALSE,
  UNIQUE(tenant_id, code)
);

CREATE INDEX IF NOT EXISTS idx_frameworks_tenant ON dos.compliance_frameworks (tenant_id);

CREATE TABLE IF NOT EXISTS dos.compliance_requirements (
  requirement_id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id VARCHAR(16) NOT NULL,
  framework_id UUID REFERENCES dos.compliance_frameworks(framework_id),
  code VARCHAR(100),
  title TEXT NOT NULL,
  description TEXT,
  status VARCHAR(50) NOT NULL DEFAULT 'pending',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_requirements_tenant ON dos.compliance_requirements (tenant_id);
